package com.gk.jobhelper.service;
import static org.junit.jupiter.api.Assertions.*;import java.io.*;import java.util.zip.*;import org.apache.poi.xssf.usermodel.XSSFWorkbook;import org.apache.poi.ss.usermodel.*;import org.junit.jupiter.api.Test;
class ExcelRecruitmentPositionExtractorTest {private final ExcelRecruitmentPositionExtractor extractor=new ExcelRecruitmentPositionExtractor(new RecruitmentExcelHeaderNormalizer());@Test void readsMultipleSheetsMergedCellsAndFiltersRows()throws Exception{byte[] bytes=workbook();RecruitmentPositionExtractionResult result=extractor.extract(new DownloadedAttachment(9L,"岗位表","application/octet-stream","XLSX",bytes),7L);assertEquals(2,result.sheetCount);assertEquals(Integer.valueOf(3),result.headerRows.get("岗位表"));assertEquals(2,result.positions.size());assertEquals("研发工程师",result.positions.get(0).getPositionName());assertEquals("国盛证券",result.positions.get(0).getOrganizationName());assertEquals(4,result.positions.get(0).getSourceRow().intValue());assertEquals("运营专员",result.positions.get(1).getPositionName());}@Test void detectsXlsxFromBytesWhenNameAndContentTypeAreUnknown()throws Exception{byte[] bytes=workbook();assertEquals("XLSX",new RecruitmentFileTypeDetector().detect("application/octet-stream","download?id=1",bytes));}@Test void distinguishesZipDocxPdfHtmlAndJson()throws Exception{RecruitmentFileTypeDetector d=new RecruitmentFileTypeDetector();assertEquals("PDF",d.detect(null,"",new byte[]{'%','P','D','F'}));assertEquals("HTML",d.detect(null,"","<html><body>x</body></html>".getBytes()));assertEquals("JSON",d.detect(null,"","{\"ok\":true}".getBytes()));assertEquals("ZIP",d.detect(null,"",zip()));}private byte[] zip()throws Exception{ByteArrayOutputStream out=new ByteArrayOutputStream();ZipOutputStream zip=new ZipOutputStream(out);zip.putNextEntry(new ZipEntry("other.txt"));zip.write(1);zip.closeEntry();zip.close();return out.toByteArray();}private byte[] workbook()throws Exception{try(XSSFWorkbook wb=new XSSFWorkbook();ByteArrayOutputStream out=new ByteArrayOutputStream()){Sheet note=wb.createSheet("说明");note.createRow(0).createCell(0).setCellValue("招聘岗位说明");Sheet sheet=wb.createSheet("岗位表");sheet.createRow(0).createCell(0).setCellValue("国盛证券招聘岗位表");Row header=sheet.createRow(2);String[] h={"招聘单位","岗位名称","招聘人数","学历要求","专业要求","工作地点","任职要求"};for(int i=0;i<h.length;i++)header.createCell(i).setCellValue(h[i]);Row first=sheet.createRow(3);first.createCell(0).setCellValue("国盛证券");first.createCell(1).setCellValue("研发工程师");first.createCell(2).setCellValue(2);first.createCell(3).setCellValue("本科");first.createCell(4).setCellValue("计算机类");first.createCell(5).setCellValue("南昌");first.createCell(6).setCellValue("Java");Row second=sheet.createRow(4);second.createCell(1).setCellValue("运营专员");second.createCell(2).setCellValue(1);sheet.addMergedRegion(new org.apache.poi.ss.util.CellRangeAddress(3,4,0,0));sheet.createRow(5).createCell(1).setCellValue("合计");sheet.createRow(6).createCell(1).setCellValue("说明：以上岗位以公告为准");wb.write(out);return out.toByteArray();}}}
